  const installInteractionPolish=()=>{if($('#interaction-polish-styles'))return;const style=document.createElement('style');style.id='interaction-polish-styles';style.textContent="html.loading,html.loading body{overflow:hidden}.global-loader{position:fixed;inset:0;z-index:50;display:grid;place-items:center;background:#17372d33;backdrop-filter:blur(2px)}.global-loader.hidden{display:none!important}.global-progress{position:fixed;inset:0 0 auto;height:4px;background:#17372d1c;overflow:hidden}.global-progress span{display:block;width:35%;height:100%;background:var(--orange);box-shadow:0 0 12px #d96935aa;animation:progress-slide 1.1s ease-in-out infinite}.loader-panel{display:grid;grid-template-columns:auto 1fr;align-items:center;gap:3px 12px;min-width:min(340px,calc(100vw - 32px));padding:18px 20px;border:1px solid var(--line);border-radius:14px;background:var(--paper);box-shadow:0 8px 12px #17372d1a;color:var(--ink)}.loader-panel small{grid-column:2;color:var(--muted);font-size:12px}.loader-spinner{width:22px;height:22px;border:3px solid var(--line);border-top-color:var(--orange);border-radius:50%;animation:loader-spin .7s linear infinite}.master-form{padding:24px}.master-form h3{margin:0;font-size:18px;letter-spacing:-.03em}.master-form:before{content:'Manage records';display:block;margin-bottom:4px;color:var(--orange-dark);font-size:10px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.master-form .controls{margin-top:16px;margin-bottom:0;padding:0}.master-form .form-grid{margin-bottom:0}.master-table{margin-top:18px}.user-access-form .form-grid{margin-bottom:0}.user-access-form #user-outlet-options{margin-top:10px}.user-access-form #user-outlet-options label{min-height:48px;cursor:pointer;transition:background .18s,border-color .18s}.user-access-form #user-outlet-options label:has(input:checked){background:var(--mint)!important;border-color:#79aa91!important}.master-form .btn{min-height:44px}@keyframes progress-slide{0%{transform:translateX(-120%)}100%{transform:translateX(320%)}}@keyframes loader-spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.global-progress span,.loader-spinner{animation:none}.global-progress span{width:100%}}@media(max-width:700px){.master-form{padding:16px}.master-form .controls,.master-form .form-grid{gap:12px}.master-table{margin-top:14px}}";document.head.appendChild(style);const decorate=()=>{const add=(selector,classes)=>{const el=$(selector)?.closest('.card');if(el)el.classList.add(...classes)};add('#new-party-name',['master-form']);add('#new-outlet-party',['master-form']);add('#new-user-contact',['master-form','user-access-form']);[['#party-rows','master-table'],['#outlet-rows','master-table'],['#user-rows','master-table']].forEach(([selector,klass])=>{$(selector)?.closest('.table-wrap')?.classList.add(klass)})};const observer=new MutationObserver(decorate);observer.observe(app,{subtree:true,childList:true});decorate()};installInteractionPolish();
  function parseCsvRows(text){const rows=[];let row=[];let cell='';let quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else{quoted=!quoted}}else if(ch===','&&!quoted){row.push(cell);cell=''}else if((ch==='\\n'||ch==='\\r')&&!quoted){if(ch==='\\r'&&text[i+1]==='\\n')i++;row.push(cell);cell='';if(row.some(value=>String(value).trim()!==''))rows.push(row);row=[]}else{cell+=ch}}if(cell!==''||row.length){row.push(cell);if(row.some(value=>String(value).trim()!==''))rows.push(row)}return rows}
  function zipU32(bytes,offset){return (bytes[offset]|(bytes[offset+1]<<8)|(bytes[offset+2]<<16)|(bytes[offset+3]<<24))>>>0}
  function zipU16(bytes,offset){return bytes[offset]|(bytes[offset+1]<<8)}
  function zipEntries(bytes){const decoder=new TextDecoder();const entries=[];let end=-1;for(let offset=bytes.length-22;offset>=Math.max(0,bytes.length-65557);offset--){if(zipU32(bytes,offset)===0x06054b50){end=offset;break}}if(end<0)throw Error('This is not a valid .xlsx file.');const directoryOffset=zipU32(bytes,end+16);const directorySize=zipU32(bytes,end+12);let offset=directoryOffset;while(offset<directoryOffset+directorySize){if(zipU32(bytes,offset)!==0x02014b50)break;const method=zipU16(bytes,offset+10);const compressedSize=zipU32(bytes,offset+20);const nameLength=zipU16(bytes,offset+28);const extraLength=zipU16(bytes,offset+30);const commentLength=zipU16(bytes,offset+32);const localOffset=zipU32(bytes,offset+42);const name=decoder.decode(bytes.slice(offset+46,offset+46+nameLength));entries.push({name,method,compressedSize,localOffset});offset+=46+nameLength+extraLength+commentLength}return entries}
  async function unzipEntry(bytes,entry){const nameLength=zipU16(bytes,entry.localOffset+26);const extraLength=zipU16(bytes,entry.localOffset+28);const start=entry.localOffset+30+nameLength+extraLength;const compressed=bytes.slice(start,start+entry.compressedSize);if(entry.method===0)return compressed;if(entry.method!==8)throw Error('This Excel file uses an unsupported compression method.');const stream=new Blob([compressed]).stream().pipeThrough(new DecompressionStream('deflate-raw'));return new Uint8Array(await new Response(stream).arrayBuffer())}
  async function parseXlsxRows(buffer){const bytes=new Uint8Array(buffer);const entries=zipEntries(bytes);const find=name=>entries.find(entry=>entry.name===name);const decoder=new TextDecoder();const sheet=find('xl/worksheets/sheet1.xml')||entries.find(entry=>entry.name.startsWith('xl/worksheets/')&&entry.name.endsWith('.xml'));if(!sheet)throw Error('Could not find the first worksheet in this Excel file.');const sharedEntry=find('xl/sharedStrings.xml');const shared=sharedEntry?Array.from(new DOMParser().parseFromString(decoder.decode(await unzipEntry(bytes,sharedEntry)),'application/xml').getElementsByTagName('si')).map(item=>Array.from(item.getElementsByTagName('t')).map(node=>node.textContent||'').join('')):[];const doc=new DOMParser().parseFromString(decoder.decode(await unzipEntry(bytes,sheet)),'application/xml');return Array.from(doc.getElementsByTagName('row')).map(row=>{const values=[];Array.from(row.getElementsByTagName('c')).forEach(cell=>{const ref=cell.getAttribute('r')||'';const letters=(ref.match(/^[A-Z]+/)||['A'])[0];let column=0;for(const letter of letters)column=column*26+letter.charCodeAt(0)-64;column-=1;const type=cell.getAttribute('t');let value='';if(type==='inlineStr'){value=Array.from(cell.getElementsByTagName('t')).map(node=>node.textContent||'').join('')}else{const raw=cell.getElementsByTagName('v')[0]?.textContent||'';value=type==='s'?(shared[Number(raw)]||''):raw}values[column]=value});return values})}
  async function parseProductFile(file){if(!file)throw Error('Choose an Excel or CSV file first.');if(file.size>5*1024*1024)throw Error('The upload must be smaller than 5 MB.');const lower=file.name.toLowerCase();return lower.endsWith('.csv')||lower.endsWith('.txt')?parseCsvRows(await file.text()):await parseXlsxRows(await file.arrayBuffer())}
  function normaliseProductUpload(rows){if(!rows.length)return {rows:[],errors:['The file has no data rows.']};const headers=rows[0].map(value=>String(value??'').trim().toLowerCase());let nameIndex=headers.findIndex(value=>value==='product name'||value==='product'||value==='name'||value.includes('product name'));let unitIndex=headers.findIndex(value=>value==='unit'||value.includes('unit'));const hasHeader=nameIndex>=0||unitIndex>=0;if(!hasHeader){nameIndex=0;unitIndex=1}if(nameIndex<0||unitIndex<0)return {rows:[],errors:['Add two columns named Product Name and Unit.']};const valid=[];const errors=[];const seen=new Set();rows.slice(hasHeader?1:0).forEach((row,index)=>{const rowNumber=hasHeader?index+2:index+1;const name=String(row[nameIndex]??'').trim();const unit=String(row[unitIndex]??'').trim().toUpperCase();if(!name&&!unit)return;if(!name){errors.push('Row '+rowNumber+': product name is required.');return}if(!['KG','PACKET','PICESS'].includes(unit)){errors.push('Row '+rowNumber+': unit must be KG, PACKET, or PICESS.');return}const key=name.toLowerCase();if(seen.has(key)){errors.push('Row '+rowNumber+': duplicate product name '+name+'.');return}seen.add(key);valid.push({name,unit})});return {rows:valid,errors}}
  function brand(){return '<div class="brand"><img class="brand-logo" src="${BRAND_LOGO_DATA}" alt="Agro Deluxe Growers"></div>'}
  function login(){app.innerHTML='<main class="login-page"><section class="login-hero">'+brand()+'<div class="login-foot">Secure access for customers and Agro Deluxe Growers administrators.</div></section><section class="login-panel"><form class="card login-card" id="login"><p class="eyebrow">Welcome back</p><h2>Sign in to continue</h2><p class="sub">Use the username assigned to your account.</p><label class="form-label">Username</label><input class="input" id="email" type="text" autocomplete="username" placeholder="Enter username" required><label class="form-label">Password</label><div class="password-wrap"><input class="input" id="password" type="password" autocomplete="current-password" placeholder="Enter your password" required><button class="show-pass" type="button" id="show">Show</button></div><div id="login-error" class="login-error hidden"></div><button class="btn btn-primary" style="width:100%;margin-top:22px" type="submit">Sign in <span>→</span></button><p class="login-help">Need access? Ask an Agro Deluxe Growers administrator to create or reset your account.</p></form></section></main>';
    $('#show').onclick=()=>{const input=$('#password');input.type=input.type==='password'?'text':'password';$('#show').textContent=input.type==='password'?'Show':'Hide'};$('#login').onsubmit=async e=>{e.preventDefault();const err=$('#login-error');err.classList.add('hidden');try{const d=await api('/api/auth/login',{method:'POST',body:JSON.stringify({login:$('#email').value,password:$('#password').value})});state.user=d.user;route()}catch(x){err.textContent=x.message;err.classList.remove('hidden')}};
  }
  const wireMobileMenu=()=>{const rail=$('.rail'),toggle=$('#mobile-menu-toggle'),backdrop=$('#mobile-menu-backdrop');if(!rail||!toggle||!backdrop)return;const close=()=>{rail.classList.remove('mobile-open');backdrop.classList.add('hidden');toggle.setAttribute('aria-expanded','false')};toggle.onclick=()=>{const open=!rail.classList.contains('mobile-open');rail.classList.toggle('mobile-open',open);backdrop.classList.toggle('hidden',!open);toggle.setAttribute('aria-expanded',String(open))};backdrop.onclick=close;document.querySelectorAll('[data-view],[data-action],#logout').forEach(button=>button.addEventListener('click',close))};
  function shell(active,content){const full=state.user.role==='SUPER_ADMIN';const nav=full?'<button class="'+(active==='orders'?'active':'')+'" data-view="orders">▦ &nbsp; DASHBOARD</button><button class="'+(active==='today-total'?'active':'')+'" data-view="today-total">▣ &nbsp; ADG PO</button><button class="'+(active==='punch'?'active':'')+'" data-view="punch">＋ &nbsp; ORDER PUNCH</button><button class="'+(active==='locations'?'active':'')+'" data-view="locations">⌂ &nbsp; CUSTOMER ON-BOARDING</button><button class="'+(active==='products'?'active':'')+'" data-view="products">◫ &nbsp; PRODUCT MASTER</button><button class="'+(active==='availability'?'active':'')+'" data-view="availability">◈ &nbsp; QUOTATIONS</button><button class="'+(active==='users'?'active':'')+'" data-view="users">◎ &nbsp; USER ACCESS</button>':'<button class="'+(active==='orders'?'active':'')+'" data-view="orders">▦ &nbsp; MAPPED OUTLET ORDERS</button><button data-action="place-order">＋ &nbsp; PLACE ORDER</button>';app.innerHTML='<div class="app-shell"><aside class="rail">'+brand()+'<nav class="rail-nav">'+nav+'</nav><div class="rail-footer">Signed in as<br><strong>'+esc(state.user.email)+'</strong><br><small>'+esc(roleLabel(state.user.role))+'</small><br><br><button class="btn btn-quiet" id="logout" style="color:var(--ink-2);padding:0">Sign out →</button></div></aside><main class="main"><button class="mobile-menu-button" id="mobile-menu-toggle" aria-expanded="false" aria-label="Open navigation">☰ <span>Menu</span></button>'+content+'</main><button class="mobile-menu-backdrop hidden" id="mobile-menu-backdrop" aria-label="Close navigation"></button></div>';wireMobileMenu();document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>adminView(b.dataset.view));document.querySelectorAll('[data-action="place-order"]').forEach(b=>b.onclick=customer);$('#logout').onclick=async()=>{await api('/api/auth/logout',{method:'POST'});state.user=null;login()}}
  function scopedShell(content){app.innerHTML='<div class="app-shell"><aside class="rail">'+brand()+'<div class="notice" style="margin-top:20px;background:var(--mint);color:var(--ink-2)">Access level<br><strong style="font-size:18px">'+esc(roleLabel(state.user.role))+'</strong></div><div class="rail-footer">Only your assigned outlets and records are available.<br><br><button class="btn btn-quiet" id="logout" style="color:var(--ink-2);padding:0">Sign out →</button></div></aside><main class="main">'+content+'</main></div>';$('#logout').onclick=async()=>{await api('/api/auth/logout',{method:'POST'});state.user=null;login()}}
  function richTextToPlain(value){const node=document.createElement('div');node.innerHTML=String(value||'');return (node.innerText||node.textContent||'').trim()}
  function wireRichText(){const box=$('#order-remarks');if(!box)return;document.querySelectorAll('[data-rich-command]').forEach(button=>{button.onmousedown=event=>event.preventDefault();button.onclick=()=>{box.focus();document.execCommand(button.dataset.richCommand,false,null)}});box.onpaste=event=>{event.preventDefault();const text=(event.clipboardData||window.clipboardData).getData('text/plain');document.execCommand('insertText',false,text)}}
  function customer(){state.outlets=[];state.products=[];state.quantities={};app.innerHTML='<div class="app-shell"><aside class="rail">'+brand()+'<div class="notice" style="margin-top:20px;background:var(--mint);color:var(--ink-2)">Customer / Party<br><strong style="font-size:22px">'+esc(state.user.party_name||'SOCIAL')+'</strong></div><div class="rail-footer">Only your assigned outlets and products are available for ordering.<br><br><button class="btn btn-quiet" id="logout" style="color:var(--ink-2);padding:0">Sign out →</button></div></aside><main class="main" id="customer-main"><button class="mobile-menu-button" id="mobile-menu-toggle" aria-expanded="false" aria-label="Open navigation">☰ <span>Menu</span></button><div class="topbar"><div><p class="eyebrow">Fresh order desk</p><h1 class="title">Order form</h1><p class="sub">Choose an outlet, set your required date, and add what you need.</p></div></div><div class="customer-layout"><section class="card form-card"><div class="form-grid"><div class="field"><label>Customer / Party</label><input class="input" value="'+esc(state.user.party_name||'SOCIAL')+'" disabled></div><div class="field"><label>Outlet</label><select class="select" id="outlet"><option>Loading outlets…</option></select></div><div class="field"><label>Order received date (DD-MM-YYYY) <span style="color:var(--orange)">*</span></label><div class="date-control"><input class="input" id="order-date" type="text" inputmode="numeric" autocomplete="off" placeholder="DD-MM-YYYY" maxlength="10" pattern="[0-9]{2}-[0-9]{2}-[0-9]{4}" required><span class="date-picker-wrap"><span class="date-picker-button" aria-hidden="true">📅</span><input class="date-picker" id="order-date-picker" type="date" aria-label="Choose order date"></span></div></div></div><div id="customer-notice" class="notice">Select an outlet to load its available product catalogue.</div><div class="search-row"><h3>Available products <span id="product-count" style="color:var(--muted);font-weight:500;font-size:13px"></span></h3><input class="input search" id="search" placeholder="Search product…"></div><div class="product-grid" id="products"><div class="empty">Your product list will appear here.</div></div><div class="field order-remarks" style="margin-top:22px"><label for="order-remarks">Remarks</label><div class="rich-toolbar" style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:7px"><button class="btn btn-quiet" type="button" data-rich-command="bold" style="padding:7px 10px;border:1px solid var(--line)">B</button><button class="btn btn-quiet" type="button" data-rich-command="italic" style="padding:7px 10px;border:1px solid var(--line)"><em>I</em></button><button class="btn btn-quiet" type="button" data-rich-command="underline" style="padding:7px 10px;border:1px solid var(--line)"><u>U</u></button><button class="btn btn-quiet" type="button" data-rich-command="insertUnorderedList" style="padding:7px 10px;border:1px solid var(--line)">• List</button></div><div id="order-remarks" class="input" contenteditable="true" role="textbox" aria-multiline="true" data-placeholder="Add delivery or handling notes…" style="min-height:104px;line-height:1.5;white-space:pre-wrap"></div><small class="sub" style="display:block;margin-top:7px">Optional. Use the formatting buttons for bold, italic, underline, or a bullet list.</small></div></section><aside class="card summary"><h3>Your order</h3><div class="summary-line"><span>Outlet</span><strong id="sum-outlet">—</strong></div><div class="summary-line"><span>Order date</span><strong id="sum-date">—</strong></div><div class="summary-total"><span>Products</span><span id="sum-count">0</span></div><button class="btn btn-primary" id="submit">Submit order →</button><button class="btn btn-quiet" id="clear" style="width:100%;margin-top:7px">Clear quantities</button></aside></div></main><button class="mobile-menu-backdrop hidden" id="mobile-menu-backdrop" aria-label="Close navigation"></button></div>';wireMobileMenu();$('#logout').onclick=async()=>{await api('/api/auth/logout',{method:'POST'});state.user=null;login()};wireRichText();loadCustomer();addPartyDashboard()}
  async function loadCustomer(){try{const d=await api('/api/customer/outlets');state.outlets=d.outlets;const select=$('#outlet');select.innerHTML=state.outlets.map(o=>'<option value="'+esc(o.id)+'">'+esc(o.name)+'</option>').join('');select.onchange=async()=>{state.selectedOutlet=select.value;state.quantities={};select.disabled=true;try{await loadProducts();renderProducts()}catch(e){toast(e.message)}finally{select.disabled=false}};if(state.outlets.length){state.selectedOutlet=state.outlets[0].id;select.value=state.selectedOutlet;select.disabled=true;try{await loadProducts()}finally{select.disabled=false}}$('#search').oninput=renderProducts;$('#clear').onclick=()=>{state.quantities={};renderProducts()};$('#submit').onclick=submitOrder;const minOrderDate=systemDateIso();$('#order-date-picker').min=minOrderDate;wireDatePicker('#order-date','#order-date-picker',()=>$('#sum-date').textContent=formatDate($('#order-date').value));$('#order-date').onchange=()=>{const iso=parseDateInput($('#order-date').value);if(iso&&iso<minOrderDate){$('#order-date').value='';$('#order-date-picker').value='';return toast('Choose today or a future date.')}$('#sum-date').textContent=formatDate($('#order-date').value)};updateSummary()}catch(e){toast(e.message)}}
  async function loadProducts(){const d=await api('/api/customer/products?outletId='+encodeURIComponent(state.selectedOutlet));state.products=d.products;$('#customer-notice').textContent=state.products.length+' products are available for this outlet. Search by name to find an item quickly.';$('#sum-outlet').textContent=state.outlets.find(x=>x.id===state.selectedOutlet)?.name||'—';renderProducts()}
  function renderProducts(){const q=($('#search')?.value||'').toLowerCase();const products=state.products.filter(p=>p.name.toLowerCase().includes(q));$('#product-count').textContent='· '+products.length;$('#products').innerHTML=products.length?products.map(p=>'<label class="product-row"><span><span class="product-name">'+esc(p.name)+'</span><span class="product-unit">Unit · '+esc(p.unit)+'</span></span><input class="input qty" type="text" inputmode="decimal" autocomplete="off" pattern="[0-9]*([.][0-9]+)?" placeholder="" data-product="'+esc(p.id)+'" value="'+(state.quantities[p.id]??'')+'"></label>').join(''):'<div class="empty">No products match that search.</div>';document.querySelectorAll('[data-product]').forEach(i=>i.oninput=()=>{i.value=normaliseQuantity(i.value);state.quantities[i.dataset.product]=i.value;updateSummary()});updateSummary()}
  function updateSummary(){const count=Object.values(state.quantities).filter(v=>Number(v)>0).length;$('#sum-count')&&($('#sum-count').textContent=count);if($('#order-date'))$('#sum-date').textContent=formatDate($('#order-date').value)}
  async function submitOrder(){const values=Object.values(state.quantities).filter(value=>String(value??'').trim()!=='');if(values.some(value=>!/^[0-9]+(?:\.[0-9]{1,3})?$/.test(String(value))||Number(value)<=0))return toast('Enter a quantity greater than 0 with up to 3 decimal places.');const items=Object.entries(state.quantities).filter(([,q])=>Number(q)>0).map(([productId,quantity])=>({productId,quantity:String(quantity)}));const remarks=$('#order-remarks')?.innerHTML||'';const orderDate=parseDateInput($('#order-date').value);if(!orderDate)return toast('Enter the order date as DD-MM-YYYY.');if(orderDate<systemDateIso())return toast('Choose today or a future date.');if(!items.length)return toast('Add at least one product quantity greater than 0.');const button=$('#submit');button.disabled=true;button.textContent='Submitting…';try{const d=await api('/api/customer/orders',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({outletId:state.selectedOutlet,orderDate,items,remarks})});success(d.order)}catch(e){toast(e.message);button.disabled=false;button.textContent='Submit order →'}}
  function success(order){const pdfReady=order.pdfStatus==='READY';app.innerHTML='<main style="min-height:100vh;padding:24px;display:grid;place-items:center"><section class="card success"><div class="success-mark">✓</div><p class="eyebrow">Agro Deluxe Growers</p><h2>Order submitted successfully</h2><p class="sub">The order has been submitted. The order PDF is available for your records and the admin team.</p><dl><dt>Order ID</dt><dd class="mono">'+esc(order.id)+'</dd><dt>Customer / Party</dt><dd>'+esc(order.partyName)+'</dd><dt>Outlet</dt><dd>'+esc(order.outletName)+'</dd><dt>Order date</dt><dd>'+esc(formatDate(order.orderDate))+'</dd><dt>PDF status</dt><dd id="pdf-status">'+(pdfReady?'<span class="pill green">Ready</span>':'<span class="pill amber">Pending</span>')+'</dd></dl><div style="display:flex;justify-content:center;gap:9px;flex-wrap:wrap"><a class="btn '+(pdfReady?'btn-primary':'btn-soft')+'" href="'+esc(order.pdfUrl||('/api/customer/orders/'+encodeURIComponent(order.id)+'/pdf'))+'" target="_blank">'+(pdfReady?'View order PDF →':'Generate order PDF →')+'</a><button class="btn btn-quiet" id="new-order">Start a new order →</button></div></section></main>';$('#new-order').onclick=customer}  async function receiving(){const content='<div class="topbar"><div><p class="eyebrow">Receiving workspace</p><h1 class="title">Confirm deliveries.</h1><p class="sub">Review assigned outlet orders, confirm received quantities, and record shortages or damage remarks.</p></div></div><section class="card notice">Only orders for outlets assigned to this receiving account are shown. Mark an order received or record a discrepancy with a remark.</section><section class="card table-wrap"><table class="table"><thead><tr><th>Order</th><th>Order date</th><th>Party</th><th>Outlet</th><th>Receipt status</th><th>Remarks</th><th>Action</th></tr></thead><tbody id="receiving-rows"><tr><td colspan="7" class="empty">Loading receiving queue…</td></tr></tbody></table></section>';scopedShell(content);const d=await api('/api/receiving/orders');$('#receiving-rows').innerHTML=d.orders.length?d.orders.map(o=>'<tr><td class="mono">'+esc(o.id)+'</td><td>'+esc(formatDate(o.order_date))+'</td><td>'+esc(o.party_name)+'</td><td>'+esc(o.outlet_name)+'</td><td>'+(o.receipt_status==='RECEIVED'?'<span class="pill green">Received</span>':o.receipt_status==='DISCREPANCY'?'<span class="pill amber">Discrepancy</span>':'<span class="pill amber">Pending</span>')+'</td><td><input class="input" data-note="'+esc(o.id)+'" placeholder="Short / damaged / remarks" value="'+esc(o.receipt_remarks||'')+'"></td><td style="white-space:nowrap"><button class="btn btn-soft" data-receive="'+esc(o.id)+'" data-status="RECEIVED">Received</button><button class="btn btn-quiet" data-receive="'+esc(o.id)+'" data-status="DISCREPANCY">Discrepancy</button></td></tr>').join(''):'<tr><td colspan="7" class="empty">No assigned orders are waiting for receiving.</td></tr>';document.querySelectorAll('[data-receive]').forEach(button=>button.onclick=async()=>{button.disabled=true;const note=document.querySelector('[data-note="'+button.dataset.receive+'"]')?.value||'';try{await api('/api/receiving/orders/'+encodeURIComponent(button.dataset.receive),{method:'POST',body:JSON.stringify({status:button.dataset.status,remarks:note})});toast(button.dataset.status==='RECEIVED'?'Order marked received.':'Discrepancy recorded.');receiving()}catch(e){toast(e.message);button.disabled=false}})}
  async function finance(){const content='<div class="topbar"><div><p class="eyebrow">Accounts & finance workspace</p><h1 class="title">Financial control view.</h1><p class="sub">Review authorized outlet orders, receipt confirmations, and document status from one account.</p></div></div><section class="grid metrics"><div class="card metric"><div class="metric-label">Authorized orders</div><div class="metric-value" id="finance-orders">—</div><div class="metric-foot">Assigned outlets</div></div><div class="card metric"><div class="metric-label">Awaiting receipt</div><div class="metric-value" id="finance-pending">—</div><div class="metric-foot">Needs outlet confirmation</div></div><div class="card metric"><div class="metric-label">Receipt discrepancies</div><div class="metric-value" id="finance-discrepancies">—</div><div class="metric-foot">Requires follow-up</div></div></section><section class="card notice">Invoice, payment, and challan records will be shown here when those records are created. Receipt status is read-only for this role.</section><section class="card table-wrap"><table class="table"><thead><tr><th>Order</th><th>Order date</th><th>Party</th><th>Outlet</th><th>Receipt</th><th>PDF</th><th>Remarks</th></tr></thead><tbody id="finance-rows"><tr><td colspan="7" class="empty">Loading finance view…</td></tr></tbody></table></section>';scopedShell(content);const d=await api('/api/finance/orders');const orders=d.orders||[];$('#finance-orders').textContent=orders.length;$('#finance-pending').textContent=orders.filter(o=>o.receipt_status==='PENDING').length;$('#finance-discrepancies').textContent=orders.filter(o=>o.receipt_status==='DISCREPANCY').length;$('#finance-rows').innerHTML=orders.length?orders.map(o=>'<tr><td class="mono">'+esc(o.id)+'</td><td>'+esc(formatDate(o.order_date))+'</td><td>'+esc(o.party_name)+'</td><td>'+esc(o.outlet_name)+'</td><td>'+(o.receipt_status==='RECEIVED'?'<span class="pill green">Received</span>':o.receipt_status==='DISCREPANCY'?'<span class="pill amber">Discrepancy</span>':'<span class="pill amber">Pending</span>')+'</td><td>'+esc(o.pdf_status||'PENDING')+'</td><td>'+esc(o.receipt_remarks||'—')+'</td></tr>').join(''):'<tr><td colspan="7" class="empty">No orders are assigned to this finance account.</td></tr>'}
