export default { async fetch(request, env, ctx) { try { await bootstrap(env); const url = new URL(request.url); if (url.pathname === "/" || url.pathname === "/orderform" || url.pathname === "/orderform/") return new Response(page(), { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } }); return await api(request, env, ctx, url.pathname); } catch (error) { console.error(error); return json({ error: "The request could not be completed." }, 500); } } };



